Cho hình vẽ sau. Trong các khẳng định sau khẳng định nào sai?

\choice
{  $Qy// Rz $ }
   { \True  ${Px}$ và ${Rz}$ không song song với nhau   }
     { $Px //Qy $  }
    { $Px //Rz  $  }
}{
\begin{tikzpicture}
            \coordinate (E) at (4, 1);
            \coordinate (D) at (3, 2);
            \coordinate (C) at (0, 0);
            \coordinate (B) at (-1, 1);
            \coordinate (A) at (-2, 2);
            \coordinate (F) at (5, 0);
             \coordinate (I) at (-3, 3);
                  \coordinate (M) at (-1, 0);
             \coordinate (N) at (1, -1);
            % Vẽ tứ giác
            \draw[thick] (C) -- (B);
            \draw[thick] (A) -- (D);
            \draw[thick] (N)--(C)--(B) -- (A)--(I);
            \draw[thick] (B) --(E);
             \draw[thick] (M)--(C) --(F);
            % Ghi nhãn các điểm

            \node[below left] at (A) {$P$};
            \node[below left] at (B){$Q$};
                      \node[above right] at (C) {$R$};
                  \node[below] at (E) {$y$};
                         \node[below] at (D) {$x$};
                        \node[below] at (F) {$z$};

                    \node[below left] at (I) {$a$};
    \draw 
            (A) pic[draw,angle radius = 7] {angle = D--A--I} node[shift={(65:13pt)}]{$ 143^\circ $}   
            ;    
            \draw 
            (B) pic[draw,angle radius = 7] {angle = E--B--I} node[shift={(65:13pt)}]{$ 143^\circ $}   
            ;    
              \draw 
            (C) pic[draw,angle radius = 7] {angle = M--C--N} node[shift={(25: -20pt)}]{$ 143^\circ $}   
            ;  
        \end{tikzpicture}
}
\loigiai{
Quan sát các góc tạo bởi đường thẳng cắt hai tia trên hình vẽ (so le trong, đồng vị, trong cùng phía): các cặp góc bằng nhau (so le trong / đồng vị) hoặc bù nhau (trong cùng phía) suy ra hai tia song song; khẳng định sai là ${Px}$ và ${Rz}$ không song song với nhau.
}\end{ex}

